// ─── The plugin-root fallback path prefix (this repo's own convention: a
// consumer gets the installed-cache CLAUDE_PLUGIN_ROOT; developing the plugin
// inside the marketplace repo itself falls back to the marketplace-relative
// path). Every sibling script + dimensions.md is resolved through this so the
// workflow is portable to any consumer repo, not just this marketplace. ────
const PLUGIN_ROOT_EXPR = "${CLAUDE_PLUGIN_ROOT:-plugins/ravenclaude-core}";
const SCRIPTS_DIR = `${PLUGIN_ROOT_EXPR}/skills/repo-review/scripts`;
const DIMENSIONS_MD = `${PLUGIN_ROOT_EXPR}/skills/repo-review/reference/dimensions.md`;

text_edits.replace:
// ─── The plugin root. The /repo-review skill passes it in as args.pluginRoot (the skill text carries the
// absolute path Claude Code substituted), and this workflow REFUSES to start without it. There is
// deliberately no fallback: any relative or project-local default would name a directory inside the
// repository under review, which may be hostile, and the scripts would run from there. ─────────────────
const PLUGIN_ROOT_EXPR =
  args && typeof args === "object" && typeof args.pluginRoot === "string" ? args.pluginRoot.trim() : "";
if (!/^\/[A-Za-z0-9._\-/~]+$/.test(PLUGIN_ROOT_EXPR) || PLUGIN_ROOT_EXPR.split("/").includes("..")) {
  return {
    error:
      `repo-sweep needs args.pluginRoot, the absolute path of the installed plugin (letters, digits, "._-/~" only, ` +
      `no ".."). Got: ${JSON.stringify(args && args.pluginRoot)}. Pass the plugin root the /repo-review skill ` +
      `shows you; this workflow never guesses one, because a guessed path could lie inside the project.`,
  };
}
const SCRIPTS_DIR = `${PLUGIN_ROOT_EXPR}/skills/repo-review/scripts`;
const DIMENSIONS_MD = `${PLUGIN_ROOT_EXPR}/skills/repo-review/reference/dimensions.md`;

